INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('41fc026fea179661cde2','Amedex 2023.pdf','990','Mixed/Unclassified','A 22-year-old woman presents with complaint of amenorrhea of one year duration. Her menses were regular before. She has no other complaints or symptoms. Physical
examination is inconclusive. Pelvis ultrasonography is unremarkable. Thyroid function tests show a TSH of 3.5mU/L (0.5-5mU’/L). Which one of the following is most likely to be the
cause of her amenorrhea?','{"A":"Mullerian agenesis.","B":"Ovarian dysgenesis.","C":"Hormonal dysfunction.","D":"Hyperthyroidism.","E":"Subclinical hyperthyroidism."}','C','Secondary amenorrhea is defined as cessation of periods after they have started. As opposed to secondary amenorrhea is defined as lack of menstrual flow by age 14 and absence
of secondary sexual characteristics or lack of menstrual flow by age 16 and presence of secondary sexual characteristics
Since this woman''s case is the cessation of previously present periods, she has secondary amenorrhea. Mullerian agenesis (option A) and ovarian dysgenesis (option B) result in
primary amenorrhea. With previous menstruation, these two conditions are unlikely. Of the uterine causes, only Asherman’s syndrome can be the cause of secondary amenorrhea.
Hyperthyroidism can cause menstruation abnormalities, particularly amenorrhea or oligomenorrhea; however, a normal TSH excludes hyperthyroidism (option D) as the etiology of
her amenorrhea. Subclinical hyperthyroidism is defined as a subnormal TSH while T3 and T4 are within normal range. This woman has a normal TSH level and does not have
subclinical hyperthyroidism (option E).
Of the options, the only explanation can be hormonal dysfunction. A hormonal dysfunction in this case could be due to conditions such as a pituitary tumor, hyperprolactinemia,
ovarian insufficiency, or polycystic ovary syndrome (PCOS).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1028","duplicate_group_id":"exact-e79678395874","duplicate_sources":[{"record_id":"41fc026fea179661cde2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":990,"source_qid":"1028"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"41fc026fea179661cde2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":990,"source_qid":"1028","domain_hint":"Mixed/Unclassified","stem":"A 22-year-old woman presents with complaint of amenorrhea of one year duration. Her menses were regular before. She has no other complaints or symptoms. Physical\nexamination is inconclusive. Pelvis ultrasonography is unremarkable. Thyroid function tests show a TSH of 3.5mU/L (0.5-5mU’/L). Which one of the following is most likely to be the\ncause of her amenorrhea?","options":{"A":"Mullerian agenesis.","B":"Ovarian dysgenesis.","C":"Hormonal dysfunction.","D":"Hyperthyroidism.","E":"Subclinical hyperthyroidism."},"source_answer":"C","source_explanation":"Secondary amenorrhea is defined as cessation of periods after they have started. As opposed to secondary amenorrhea is defined as lack of menstrual flow by age 14 and absence\nof secondary sexual characteristics or lack of menstrual flow by age 16 and presence of secondary sexual characteristics\nSince this woman''s case is the cessation of previously present periods, she has secondary amenorrhea. Mullerian agenesis (option A) and ovarian dysgenesis (option B) result in\nprimary amenorrhea. With previous menstruation, these two conditions are unlikely. Of the uterine causes, only Asherman’s syndrome can be the cause of secondary amenorrhea.\nHyperthyroidism can cause menstruation abnormalities, particularly amenorrhea or oligomenorrhea; however, a normal TSH excludes hyperthyroidism (option D) as the etiology of\nher amenorrhea. Subclinical hyperthyroidism is defined as a subnormal TSH while T3 and T4 are within normal range. This woman has a normal TSH level and does not have\nsubclinical hyperthyroidism (option E).\nOf the options, the only explanation can be hormonal dysfunction. A hormonal dysfunction in this case could be due to conditions such as a pituitary tumor, hyperprolactinemia,\novarian insufficiency, or polycystic ovary syndrome (PCOS).","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","duration"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e79678395874fb08c5a741d4e4a2c49556fed775","duplicate_group_id":"exact-e79678395874","duplicate_sources":[{"record_id":"41fc026fea179661cde2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":990,"source_qid":"1028"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
