:"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"78ec0fa6586650a38dde773f0867a4b1e424720e","duplicate_group_id":"exact-78ec0fa65866","duplicate_sources":[{"record_id":"d1113877d33e9460a357","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1011,"source_qid":"1391"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
