INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f861b3fd83d69c454792','Amedex 2023.pdf','1027','Mixed/Unclassified','A 32-year-old woman with history of primary infertility presents to your clinic with a 6-month history of secondary amenorrhea. Which one of the following hormones, if significantly elevated, would signify that pregnancy has already occurred?','{"A":"Serum prolactin (PRL).","B":"Serum leuteinizing hormone (LH).","C":"Serum follicle stimulating hormone (FSH).","D":"Serum progesterone.","E":"Serum estradiol."}','B','Estradiol, prolactin and progesterone all are elevated during the pregnancy, but they may be also raised in other pathological conditions without pregnancy.
FSH is suppressed throughout pregnancy due to the negative feedback signaled by elevated eestradiol.
During the pregnancy β-HCG reaches it maximum plasma levels around 11-12 weeks of gestation and remains high throughout the pregnancy.
LH, FSH, TSH and HCG have identical alpha subunits. But only LH has a beta subunit (physiologically active component of LH) with similar structure to that of HCG; therefoe, virtually in all LH assays during gestation the LH will be reported high.
Although LH levels of 100-150 IU/L may be seen in other conditions such as polycystic ovarian syndrome (PCOS), levels above 200 IU/L are highly indicative of pregnancy.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-8d9433d1fde6","duplicate_sources":[{"record_id":"f861b3fd83d69c454792","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1027,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"f861b3fd83d69c454792","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1027,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 32-year-old woman with history of primary infertility presents to your clinic with a 6-month history of secondary amenorrhea. Which one of the following hormones, if significantly elevated, would signify that pregnancy has already occurred?","options":{"A":"Serum prolactin (PRL).","B":"Serum leuteinizing hormone (LH).","C":"Serum follicle stimulating hormone (FSH).","D":"Serum progesterone.","E":"Serum estradiol."},"source_answer":"B","source_explanation":"Estradiol, prolactin and progesterone all are elevated during the pregnancy, but they may be also raised in other pathological conditions without pregnancy.\nFSH is suppressed throughout pregnancy due to the negative feedback signaled by elevated eestradiol.\nDuring the pregnancy β-HCG reaches it maximum plasma levels around 11-12 weeks of gestation and remains high throughout the pregnancy.\nLH, FSH, TSH and HCG have identical alpha subunits. But only LH has a beta subunit (physiologically active component of 