INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9645a2cffd2453525d9a','Amedex 2023.pdf','1034','Mixed/Unclassified','A 50-year-old woman presents to you complaining of hot flushes disturbing her daily life. Her medical history includes hysterectomy due to uterine fibroid and an episode of deep vein thrombosis 18 months ago. She asks for hormone replace therapy
(HRT). Which one of the following would be the best treatment option for her?','{"A":"Low-dose estradiol valerate.","B":"Low-dose combined estrogen and progesterone.","C":"Progesterone.","D":"Estrogen dermal patch.","E":"Estrogen implants."}','D','Estrogen-only HRT is more effective than combined HRT and indicated whenever endometrial cancer caused by unopposed estrogen is not a concern, such as in this woman who does not have a uterus.
Oral estrogen is known to stimulate the coagulation pathway and is associated with increased risk of thromboembolism; hence, systemic estrogen is not a good option for her. However, estrogen dermal patches have not been shown to be
associated with increased risk of venous thromboembolism and can be safely use for this woman. Estrogen implants are the second-line option if the transdermal patches fail to control the symptoms.
 
TOPIC REVIEW
Combination HRT is associated with a 2- to 5-fold relative risk of venous thromboembolism (VTE). The risk is 1.2 -1.5 in estrogen HRT. Natural progesterone is not associated with increased risk of VTE, whereas, synthetic progesterones such as
medroxy progesterone acetate (Depo Provera®) has been shown to be associated with a slight increase in risk of VTE.
Studies comparing oral and transdermal estorgen preparations have demonstrated that transdermally administered estrogen has little, if any, effect in increasing prothrombotic substances (due to first-pass effect in the liver) and may have beneficial
effects on proinflammatory markers, including C-reactive protein, prothrombin activation peptide, and antithrombin activity. Also, in contrast to oral estrogen, transdermal estrogen may have a suppressive effect on tissue plasminogen activator and
plasminogen activator inhibitor activity.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-90f28d7c4438","duplicate_sources":[{"record_id":"9645a2cffd2453525d9a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1034,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"9645a2cffd2453525d9a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1034,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 50-year-old woman presents to you complaining of hot flushes disturbing her daily life. Her medical history includes hysterectomy due to uterine fibroid and an episode of deep vein thrombosis 18 months ago. She asks for hormone replace therapy\n(HRT). Which one of the following would be the best treatment option for her?","options":{"A":"Low-dose estradiol valerate.","B":"Low-dose combined estrogen and progesterone.","C":"Progesterone.","D":"Estrogen dermal patch.","E":"Estrogen implants."},"source_answer":"D","source_explanation":"Estrogen-only HRT is more effective than combined HRT and indicated whenever endometrial cancer caused by unopposed estrogen is not a concern, such as in this woman who does not have a uterus.\nOral estrogen is known to stimulate the coagulation pathway and is associated with increased risk of thromboembolism; hence, systemic estrogen is not a good option for her. However, estrogen dermal patches have not been shown to be\nassociated with increased risk of venous thromboembolism and can be safely use for this woman. Estrogen implants are the second-line option if the transdermal patches fail to control the symptoms.\n \nTOPIC REVIEW\nCombination HRT is associated with a 2- to 5-fold relative risk of venous thromboembolism (VTE). The risk is 1.2 -1.5 in estrogen HRT. Natural progesterone is not associated with increased risk of VTE, whereas, synthetic progesterones such as\nmedroxy progesterone acetate (Depo Provera®) has been shown to be associated with a slight increase in risk of VTE.\nStudies comparing oral and transdermal estorgen preparations have demonstrated that transdermally administered estrogen has little, if any, effect in increasing prothrombotic substances (due to first-pass effect in the liver) and may have beneficial\neffects on proinflammatory markers, including C-reactive protein, prothrombin activation peptide, and antithrombin activity. Also, in contrast to oral estrogen, transdermal estrogen may have a suppressive effect on tissue plasminogen activator and\nplasminogen activator inhibitor activity.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"90f28d7c4438285f6bd41789ab0f41ea4440f3af","duplicate_group_id":"exact-90f28d7c4438","duplicate_sources":[{"record_id":"9645a2cffd2453525d9a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1034,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance