INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a36323713530a05c8504','Amedex 2023.pdf','1040','Mixed/Unclassified','A 28-year-old woman comes to your practice because of nausea, vomiting and diarrhea after she had a burger in a local restaurant. She is on oral contraceptive pills. She has not missed her pills even when she was severely sick. Which one of the
following would be the most appropriate advice to give her regarding contraception and the pills?','{"A":"She should continue the pills and use condom for 7 days.","B":"She should stop the pills now and starts a new pack for the next cycle.","C":"She should discontinue the pills and use a barrier method until diarrhea settles.","D":"Give her ciprofloxacin and review in 2 days.","E":"She should avoid sexual activity for 3 weeks."}','A','In the following situations, the effectiveness of oral contraceptive pills is reduced and additional measures should be taken:
An active pill is forgotten to be taken for more than 24 hours from the last pill.
Severe diarrhea or vomiting lasting more than 24 hours. Virtually, this has the same effect of not having the next pill for more than 24 hours after the last.
In situations like these, the woman should take the next pill on the routine schedule but an extra protection method such as barrier methods should be used, or intercourse avoided for 7 days.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-51784213b1cb","duplicate_sources":[{"record_id":"a36323713530a05c8504","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1040,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"a36323713530a05c8504","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1040,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 28-year-old woman comes to your practice because of nausea, vomiting and diarrhea after she had a burger in a local restaurant. She is on oral contraceptive pills. She has not missed her pills even when she was severely sick. Which one of the\nfollowing would be the most appropriate advice to give her regarding contraception and the pills?","options":{"A":"She should continue the pills and use condom for 7 days.","B":"She should stop the pills now and starts a new pack for the next cycle.","C":"She should discontinue the pills and use a barrier method until diarrhea settles.","D":"Give her ciprofloxacin and review in 2 days.","E":"She should avoid sexual activity for 3 weeks."},"source_answer":"A","source_explanation":"In the following situations, the effectiveness of oral contraceptive pills is reduced and additional measures should be taken:\nAn active pill is forgotten to be taken for more than 24 hours from the last pill.\nSevere diarrhea or vomiting lasting more than 24 hours. Virtually, this has the same effect of not having the next pill for more than 24 hours after the last.\nIn situations like these, the woman should take the next pill on the routine schedule but an extra protection method such as barrier methods should be used, or intercourse avoided for 7 days.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["contracept"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"51784213b1cbae34ecf678965876c78d3d3972d7","duplicate_group_id":"exact-51784213b1cb","duplicate_sources":[{"record_id":"a36323713530a05c8504","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1040,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
