INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('22bbcf03bd208e1b1c92','Amedex 2023.pdf','1042','Mixed/Unclassified','A 20-year-old woman presents to your practice with complaints of episodes of erratic vaginal bleeding for the past four months after she started taking combined oral contraceptive pills (Microgynon 30). She is sexually active and uses condoms for
prevention of sexually transmitted infections as well. Which one of the following would be the most appropriate advice?','{"A":"She should switch to progestogen-only pills.","B":"She should switch to a new combined pill with ethinylestradiole 50mcg.","C":"She should use intrauterine contraceptive device.","D":"She should continue the same oral contraceptive pill.","E":"She should use Implanon®."}','B','Erratic breakthrough vaginal bleeding is seen in 30% of women who are recently started on combined oral contraceptive pills (COCPs). This percentage, however, decrease to only 10% after 3 months.
This problem is more common with preparations that contain low-dose estrogen. If the history of erratic bleeding is less than three months, only reassurance is required as the condition resolves after three months of use in most women. Once the
problem persists beyond three months, the next best step would be increasing the dose of estrogen (e.g. to 50mcg).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-cd4cd03b34f2","duplicate_sources":[{"record_id":"22bbcf03bd208e1b1c92","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1042,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"22bbcf03bd208e1b1c92","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1042,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 20-year-old woman presents to your practice with complaints of episodes of erratic vaginal bleeding for the past four months after she started taking combined oral contraceptive pills (Microgynon 30). She is sexually active and uses condoms for\nprevention of sexually transmitted infections as well. Which one of the following would be the most appropriate advice?","options":{"A":"She should switch to progestogen-only pills.","B":"She should switch to a new combined pill with ethinylestradiole 50mcg.","C":"She should use intrauterine contraceptive device.","D":"She should continue the same oral contraceptive pill.","E":"She should use Implanon®."},"source_answer":"B","source_explanation":"Erratic breakthrough vaginal bleeding is seen in 30% of women who are recently started on combined oral contraceptive pills (COCPs). This percentage, however, decrease to only 10% after 3 months.\nThis problem is more common with preparations that contain low-dose estrogen. If the history of erratic bleeding is less than three months,