INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('da8233c365bacfd212a2','Amedex 2023.pdf','1044','Mixed/Unclassified','Which one of the following is the first-line contraceptive choice for women with epilepsy, who are on enzyme-inducing anti-epileptic drugs?','{"A":"Combined oral contraceptive pills with low-dose estrogen.","B":"Levonorgestrel-releasing intrauterine contraceptive device.","C":"Barrier methods.","D":"Progestin-only pills.","E":"Combined oral contraceptive pills with high-dose estrogen."}','B','There are a few management options for women on enzyme-inducing medications, levonorgestrel-releasing intrauterine contraceptive device (Mirena®) is the first-line contraceptive choice. Other methods to consider are male condom or increasing
the dose of estrogen. 
Mirena® is a very effective form of contraception. The effect of progesterone is mediated locally and is not affected by enzyme-inducing antiepileptic drugs. Failure rate is 1%, with prompt reversion of fertility once the contraception is withdrawn.
Contraindications to intrauterine devices include:
Pregnancy
Active pelvic inflammatory disease (PID) or the history of acute PID within the past 3 months
Postpartum or post-abortion endometritis in the past 3 months
Uterine abnormalities resulting in anatomic distortion
Genital bleeding of unknown etiology
Untreated vaginitis or cervicitis, including bacterial vaginosis
Previously inserted IUD still in place
Relative contraindications:
Menorrhagea
Dysmenorrhea
Very large or very small uterus (>5.5cm or <0.9cm)
Anemia
Defective immune system
Impaired clotting mechanism
Valvular heart disease
Patient or partner with multiple sexual partners
Combined oral contraceptive pills are not the first-line option for contraception in patients taking enzyme inducing anti-epileptic drugs. If a patient chooses to use combined oral contraceptive pills, those with higher estrogen content should be
considered.
Progestin-only pills are not suitable for women who are on enzyme inducing antiepileptic drugs which can cause reduction in circulating levels of progestin..','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-fe46675e84dd","duplicate_sources":[{"record_id":"da8233c365bacfd212a2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1044,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"da8233c365bacfd212a2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1044,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Which one of the following is the first-line contraceptive choice for women with epilepsy, who are on enzyme-inducing anti-epileptic drugs?","options":{"A":"Combined oral contraceptive pills with low-dose estrogen.","B":"Levonorgestrel-releasing intrauterine contraceptive device.","C":"Barrier methods.","D":"Progestin-only pills.","E":"Combined oral contraceptive pills with high-dose estrogen."},"source_answer":"B","source_explanation":"There are a few management options for women on enzyme-inducing medications, levonorgestrel-releasing intrauterine contraceptive device (Mirena®) is the first-line contraceptive choice. Other methods to consider are male condom or increasing\nthe dose of estrogen. \nMirena® is a very effective form of contraception. The effect of progesterone is mediated locally and is not affected by enzyme-inducing antiepileptic drugs. Failure rate is 1%, with prompt reversion of fertility once the contraception is withdrawn.\nContraindications to intrauterine devices include:\nPregnancy\nActive pelvic inflammatory disease (PID) or the history of acute PID within the past 3 months\nPostpartum or post-abortion endometritis in the past 3 months\nUterine abnormalities resulting in anatomic distortion\nGenital bleeding of unknown etiology\nUntreated vaginitis or cervicitis, including bacterial vaginosis\nPreviously inserted IUD still in place\nRelative contraindications:\nMenorrhagea\nDysmenorrhea\nVery large or very small uterus (>5.5cm or <0.9cm)\nAnemia\nDefective immune system\nImpaired clotting mechanism\nValvular heart disease\nPatient or partner with multiple sexual partners\nCombined oral contraceptive pills are not the first-line option for contraception in patients taking enzyme inducing anti-epileptic drugs. If a patient chooses to use combined oral contraceptive pills, those with higher estrogen content should be\nconsidered.\nProgestin-only pills are not suitable for women who are on enzyme inducing antiepileptic drugs which can cause reduction in circulating levels of progestin..","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","contracept","dose","drug","management","pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"fe46675e84ddf6137d60d452ea45e96ecb6c0fc5","duplicate_group_id":"exact-fe46675e84dd","duplicate_sources":[{"record_id":"da8233c365bacfd212a2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1044,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
