INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b7fdf1e317fcf205e89a','Amedex 2023.pdf','1050','Mixed/Unclassified','A 23-year-old university student visits your clinic for advice about contraception. She reports migraine-type headaches once or twice a month for the past 3 months. She already has been on combined oral contraceptive pills for the past 2 years.
Which one of the following would be the most appropriate advice?','{"A":"Discontinuation of combined oral contraceptive pills.","B":"Stopping the combined oral contraceptive pills and starting progesterone only pills (POP).","C":"Continuation of combined oral contraceptive pills.","D":"Refer her to an obstetrician for further management.","E":"Tell her to use barrier methods, as those would be safer."}','B','Since this patient has developed migraine headache while on combined oral contraceptives (COCs), the best advice would be discontinuation of COCs and using progestogen-only pills (POPs) after discussion of potential adverse effects with her.
COCs are generally considered safe in women who have migraine without aura under the age of 35; however, if the migraine has started after the initiation of COCs, COCs will be relatively contraindicated.
Migraine with aura remains the absolute contraindication to the use of COCs because of the increased risk of ischemic stroke.
Progestogen-only methods provide a useful contraceptive option for any woman, in whom estrogen is contraindicated, irrespective of age or parity. No harmful effects have been found on long-term follow-up of children whose mother used
progesterone-only methods. This makes POPs a good contraceptive option for lactating women as well.
Indications to use progesterone-only methods as the first-line options include:
Hypertension
Superficial thrombophlebitis
History of thromboembolism
Biliary tract disease
Thyroid disease
Epilepsy
Diabetes mellitus without vascular disease
Migraine – see the explanations above
lactation
Chloasma
Contraindications to progesterone-only methods are:
Pregnancy
Breast cancer
Undiagnosed genital tract bleeding
History of or risk factor for ectopic pregnancy
Active liver disease
Liver cirrhosis','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-a042bbafe71e","duplicate_sources":[{"record_id":"b7fdf1e317fcf205e89a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1050,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"b7fdf1e317fcf205e89a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1050,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 23-year-old university student visits your clinic for advice about contraception. She reports migraine-type headaches once or twice a month for the past 3 months. She already has been on combined oral contraceptive pills for the past 2 years.\nWhich one of the following would be the most appropriate advice?","options":{"A":"Discontinuation of combined oral contraceptive pills.","B":"Stopping the combined oral contraceptive pills and starting progesterone only pills (POP).","C":"Continuation of combined oral contraceptive pills.","D":"Refer her to an obstetrician for further management.","E":"Tell her to use barrier methods, as those would be safer."},"source_answer":"B","source_explanation":"Since this patient has developed migraine headache while on combined oral contraceptives (COCs), the best advice would be discontinuation of COCs and using progestogen-only pills (POPs) after discussion of potential adverse effects with her.\nCOCs are generally considered safe in women who have migraine without aura under the age of 35; however, if the migraine has started after the initiation of COCs, COCs will be relatively contraindicated.\nMigraine with aura remains the absolute contraindication to the use of COCs because of the increased risk of ischemic stroke.\nProgestogen-only methods provide a useful contraceptive option for any woman, in whom estrogen is contraindicated, irrespective of age or parity. No harmful effects have been found on long-term follow-up of children whose mother used\nprogesterone-only methods. This makes POPs a good contraceptive option for lactating women as well.\nIndications to use progesterone-only methods as the first-line options include:\nHypertension\nSuperficial thrombophlebitis\nHistory of thromboembolism\nBiliary tract disease\nThyroid disease\nEpilepsy\nDiabetes mellitus without vascular disease\nMigraine – see the explanations above\nlactation\nChloasma\nContraindications to progesterone-only methods are:\nPregnancy\nBreast cancer\nUndiagnosed genital tract bleeding\nHistory of or risk factor for ectopic pregnancy\nActive liver disease\nLiver cirrhosis","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","contracept","diabetes","hypertension","pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a042bbafe71eb0ddb2b33d4f96b9ee351947a32a","duplicate_group_id":"exact-a042bbafe71e","duplicate_sources":[{"record_id":"b7fdf1e317fcf205e89a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1050,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanati