INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('454b2110e22bf942335a','Amedex 2023.pdf','1052','Mixed/Unclassified','A 36-year-old woman comes to your office for advice regarding oral contraception. She is currently on Microgynon 30 and is satisfied with it. She has 2 children, does not smoke and enjoys good health. On examination, you find that her blood
pressure is 150/100mmHg. Another reading in 20 minutes shows the sameblood pressure. Which one of the following would be the next best step in management?','{"A":"Continue the same OCP, but start her on antihypertensive medications.","B":"Stop OCP and give antihypertensive medications.","C":"Use an OCP with lower doses of estrogen.","D":"Start her on progestogen-only pills (POPs).","E":"Continue the same OCP without further action."}','D','Evidence suggests that combined oral contraceptive pills (COC) have a small adverse effect on blood pressure with an average increase of 8mmHg for systolic and 6mmHg for diastolic pressure. However, a minority of women may suffer severe
hypertension induced by COC.
Unlike COCs, progesterone-only pills do not appear to induce an increase in blood pressure; therefore the next best step in management is switching to POPs.
In women with well-controlled and monitored hypertension ,who are 35 years or younger, a trial of combined oral contraceptives may be appropriate as long as the patient is otherwise healthy, shows no signs of end-organ vascular disease, and does
not smoke. If blood pressure remains well controlled several months after the trial is started, combination contraceptive may be continued.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-1552997d784f","duplicate_sources":[{"record_id":"454b2110e22bf942335a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1052,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"454b2110e22bf942335a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1052,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 36-year-old woman comes to your office for advice regarding oral contraception. She is currently on Microgynon 30 and is satisfied with it. She has 2 children, does not smoke and enjoys good health. On examination, you find that her blood\npressure is 150/100mmHg. Another reading in 20 minutes shows the sameblood pressure. Which one of the following would be the next best step in management?","options":{"A":"Continue the same OCP, but start her on antihypertensive medications.","B":"Stop OCP and give antihypertensive medications.","C":"Use an OCP with lower doses of estrogen.","D":"Start her on progestogen-only pills (POPs).","E":"Continue the same OCP without further action."},"source_answer":"D","source_explanation":"Evidence suggests that combined oral contraceptive pills (COC) have a small adverse effect on blood pressure with an average increase of 8mmHg for systolic and 6mmHg for diastolic pressure. However, a minority of women may suffer severe\nhypertension induced by COC.\nUnlike COCs