INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ecb09f05259f8d2fafd9','Amedex 2023.pdf','1053','Mixed/Unclassified','A 24-year-old woman is at your office for prescription of oral contraceptive pills. She has the history of epilepsy for the past 5 years and is on carbamazepine. She has not had any episode of seizure in the past 6 months. Which one of the following
would be the most appropriate advice?','{"A":"Cease carbamazepine.","B":"Reduce the dose of carbamazepine.","C":"Prescribe high-dose oral contraceptive pills (microgynon 50).","D":"Prescribe low-dose oral contraceptive pills (microgynon 30) and follow up in 3 months.","E":"Advise her to use condoms only."}','C','Since this patient has been stable on carbamazepine, cessation of carbamazepine or dose reduction is not wise, but it should be remembered that some antiepileptic drugs such as carbamazepine can induce liver cytochrome enzyme activity and
increase the metabolism of the active gradients of oral contraceptive pills (OCPs), progestin-only pills and progesterone implants. Concomitant use of anti-epileptic drugs (AEDs) reduces the efficacy of oral contraceptive pills by 40-50%. This can
cause less effective protection against pregnancy and ‘pill failure’.
With low-dose OCPs (microgynon 30), this reduction in efficacy will result in a 6% failure rate. This is why it is recommended that women on antiepileptic drugs take high-dose OCPs (microgynon 50) to minimize the risk of ‘pill failure’. Even by
such increase, there is a small risk of unplanned pregnancy, and barrier methods can be considered along with microgynon 50 after discussion with the patient.
Mirena® is often the best option to offer, as it is unaffected by enzyme-inducing drugs with provision of excellent protection, and should be offered as an option unless IUCDs are contraindicated. Depo Provera® is another good choice.
NOTE - COCs, POPs and Implanon® are affected by enzyme-inducing drugs. These drugs have no imapct on Mirena® and Depo Provera®.
The following antiepileptic drugs can induce cytochrome enzymes and cause pill failure:
Phenobarbital
Primidone
Phenytoin
Carbamazepine
Oxcarbazepine
Topiramate','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-d36f6a268aaf","duplicate_sources":[{"record_id":"ecb09f05259f8d2fafd9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1053,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"ecb09f05259f8d2fafd9","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1053,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 24-year-old woman is at your office for prescription of oral contraceptive pills. She has the history of epilepsy for the past 5 years and is on carbamazepine. She has not had any episode of seizure in the past 6 months. Which one of the following\nwould be the most appropriate advice?","options":{"A":"Cease carbamazepine.","B":"Reduce the dose of carbamazepine.","C":"Prescribe high-dose oral contraceptive pills (microgynon 50).","D":"Prescribe low-dose oral contraceptive pills (microgynon 30) and follow up in 3 months.","E":"Advise her to use condoms only."},"source_answer":"C","source_explanation":"Since this patient has been stable on carbamazepine, cessation of carbamazepine or dose reduction is not wise, but it should be remembered that some antiepileptic drugs such as carbamazepine can induce liver cytochrome enzyme activity and\nincrease the metabolism of the active gradients of oral contraceptive pills (OCPs), progestin-only pills and progesterone implants. Concomitant use of anti-epileptic drugs (AEDs) reduces the efficacy of oral contraceptive pills by 40-50%. This can\ncause less effective protection against pregnancy and ‘pill failure’.\nWith low-dose OCPs (microgynon 30), this reduction in efficacy will result in a 6% failure rate. This is why it is recommended that women on antiepileptic drugs take high-dose OCPs (microgynon 50) to minimize the risk of ‘pill failure’. Even by\nsuch increase, there is a small risk of unplanned pregnancy, and barrier methods can be considered along with microgynon 50 after discussion with the patient.\nMirena® is often the best option to offer, as it is unaffected by enzyme-inducing drugs with provision of excellent protection, and should be offered as an option unless IUCDs are contraindicated. Depo Provera® is another good choice.\nNOTE - COCs, POPs and Implanon® are affected by enzyme-inducing drugs. These drugs have no imapct on Mirena® and Depo Provera®.\nThe following antiepileptic drugs can induce cytochrome enzymes and cause pill failure:\nPhenobarbital\nPrimidone\nPhenytoin\nCarbamazepine\nOxcarbazepine\nTopiramate","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["contracept","dose","drug","pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d36f6a268aaf60b0e4588e6d925c649e8a66dd01","duplicate_group_id":"exact-d36f6a268aaf","duplicate_sources":[{"record_id":"ecb09f05259f8d2fafd9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1053,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provena