INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5e0f77a67a148ba62dc6','Amedex 2023.pdf','1068','Mixed/Unclassified','Martha, 42 years of age, has developed a rash characteristic of chicken pox today, just 5 days prior to her expected date of delivery. She is 37 weeks pregnant. Which one of the following is the most appropriate management to prevent neonatal
chickenpox?','{"A":"Antiviral therapy.","B":"Consultation with an infectious diseases expert.","C":"Varicella zoster immunoglobulin to the mother before delivery.","D":"Varicella zoster immunoglobulin to the baby after delivery.","E":"Follow up for early onset sepsis."}','D','Management of neonates exposed to maternal varicella zoster (maternal chickenpox) is according to the following guidelines:
Presentation of the symptoms >7 days before delivery:
No varicella zoster immunoglobulin (VZIG) required.
No isolation required.
Encourage breastfeeding.
No other interventions required even if baby has chickenpox at or very soon after birth, unless preterm < 28 weeks gestation or low birth weight <1,000 g.
NOTE - Very preterm neonates (≤ 28 weeks gestation) born with chickenpox should receive intravenous aciclovir 20 mg/kg every 8 hours as a slow infusion (in 1-2 hours)
Maternal chickenpox 7 days before to 2 days after birth
Give newborn VZIG 200 IU (one vial) intramuscularly (IM) immediately after birth. VZIG should be given as soon as possible within the first 24 hours of birth but may be given up to 72 hours.
Discharge term neonates as soon as possible.
No isolation required.
Encourage breastfeeding.
Maternal chickenpox > 2 to 28 days after birth
If neonate < 28 weeks gestation or 1000 g birth weight, give VZIG (preferably within 96 hours but can be given up to 10 days post-maternal rash.
Due to the increased risk of severe varicella in newborns of seronegative women (if the mother has no personal history of infection with VZV), give VZIG to neonates exposed to varicella between 2 to 28 days of age.
Discharge term neonates as soon as possible.
No isolation required.
Encourage breastfeeding.
NOTE - Some experts give VZIG 200 IU (one vial) IM when mothers develop chickenpox to term babies who are more than 2 to 28 days of age but there is little evidence to support this.
This woman has developed chickenpox 5 days before delivery; therefore, the neonate should receive ZIG immediately after birth. Although antiviral therapy, preferrably with acyclovir, will benefit the mother if she presents within 24 hours of
appearance of the rash, it will not effectively reduce the risk of transmission to the neonate at this stage of pregnancy.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"205","duplicate_group_id":"exact-1c002a20ed0c","duplicate_sources":[{"record_id":"5e0f77a67a148ba62dc6","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1068,"source_qid":"205"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5e0f77a67a148ba62dc6","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1068,"source_qid":"205","domain_hint":"Mixed/Unclassified","stem":"Martha, 42 years of age, has developed a rash characteristic of chicken pox today, just 5 days prior to her expected date of delivery. She is 37 weeks pregnant. Which one of the following is the most appropriate management to prevent neonatal\nchickenpox?","options":{"A":"Antiviral therapy.","B":"Consultation with an infectious diseases expert.","C":"Varicella zoster immunoglobulin to the mother before delivery.","D":"Varicella zoster immunoglobulin to the baby after delivery.","E":"Follow up for early onset sepsis."},"source_answer":"D","source_explanation":"Management of neonates exposed to maternal varicella zoster (maternal chickenpox) is according to the following guidelines:\nPresentation of the symptoms >7 days before delivery:\nNo varicella zoster immunoglobulin (VZIG) required.\nNo isolation required.\nEncourage breastfeeding.\nNo other interventions required even if baby has chickenpox at or very soon after birth, unless preterm < 28 weeks gestation or low birth weight <1,000 g.\nNOTE - Very preterm neonates (≤ 28 weeks gestation) born with chickenpox should receive intravenous aciclovir 20 mg/kg every 8 hours as a slow infusion (in 1-2 hours)\nMaternal chickenpox 7 days before to 2 days after birth\nGive newborn VZIG 200 IU (one vial) intramuscularly (IM) immediately after birth. VZIG should be given as soon as possible within the first 24 hours of birth but may be given up to 72 hours.\nDischarge term neonates as soon as possible.\nNo isolation required.\nEncourage breastfeeding.\nMaternal chickenpox > 2 to 28 days after birth\nIf neonate < 28 weeks gestation or 1000 g birth weight, give VZIG (preferably within 96 hours but can be given up to 10 days post-maternal rash.\nDue to the increased risk of severe varicella in newborns of seronegative women (if the mother has no personal history of infection with VZV), give VZIG to neonates exposed to varicella between 2 to 28 days of age.\nDischarge term neonates as soon as possible.\nNo isolation required.\nEncourage breastfeeding.\nNOTE - Some experts give VZIG 200 IU (one vial) IM when mothers develop chickenpox to term babies who are more than 2 to 28 days of age but there is little evidence to support this.\nThis woman has developed chickenpox 5 days before delivery; therefore, the neonate should receive ZIG immediately after birth. Although antiviral therapy, preferrably with acyclovir, will benefit the mother if she presents within 24 hours of\nappearance of the rash, it will not effectively reduce the risk of transmission to the neonate at this stage of pregnancy.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","guideline","management","pregnan","therapy"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1c002a20ed0c42cd80d0886c00c6063f4117b828","duplicate_group_id":"exact-1c002a20ed0c","duplicate_sources":[{"record_id":"5e0f77a67a148ba62dc6","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1068,"source_qid":"205"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
