INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('133c11e817567dc229c8','Amedex 2023.pdf','1070','Mixed/Unclassified','A 10-month-old female infant is brought to you for assessment. She was born via an uneventful vaginal delivery. Her mother was found to have positive titers of anti-hepatitis C virus antibodies. Which one of the following would the most appropriate
next step in management of this baby?','{"A":"Wait until 18 months and check the baby’s anti HCV antibody titre.","B":"Check HCV RNA serology (PCR) now.","C":"Refer to specialist for further management.","D":"Start the baby on ribavirin and interferon.","E":"Reassure that these antibodies are from the mother’s blood and would be cleared with time."}','A','The Royal Australian and New Zealand College of Obstetricians and Gynecologists recommend that all infants of HCV positive mothers should be screened at 12-18 months of age to determine whether they have been infected. The delay allows full
clearance of maternal antibody in the infant and avoiding confusing results. Screening should be performed by antibody and, if positive, HCV RNA by PCR.
Since this child is only 10 months, the next best step would be waiting until she reaches 18 months to let the circulating antibodies cleared. If the antibody titer remains positive beyond this time, HCV RNA serology would be the next step.
Positive HCV RNA serology indicates presence of hepatitis C virus and infection of the infant. If that is the case, the neonate should be referred to a specialist for further management.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"207","duplicate_group_id":"exact-387db531fd6e","duplicate_sources":[{"record_id":"133c11e817567dc229c8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1070,"source_qid":"207"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"133c11e817567dc229c8","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1070,"source_qid":"207","domain_hint":"Mixed/Unclassified","stem":"A 10-month-old female infant is brought to you for assessment. She was born via an uneventful vaginal delivery. Her mother was found to have positive titers of anti-hepatitis C virus antibodies. Which one of the following would the most appropriate\nnext step in management of this baby?","options":{"A":"Wait until 18 months and check the baby’s anti HCV antibody titre.","B":"Check HCV RNA serology (PCR) now.","C":"Refer to specialist for further management.","D":"Start the baby on ribavirin and interferon.","E":"Reassure that these antibodies are from the mother’s blood and would be cleared with time."},"source_answer":"A","source_explanation":"The Royal Australian and New Zealand College of Obstetricians and Gynecologists recommend that all infants of HCV positive mothers should be screened at 12-18 months of age to determine whether they have been infected. The delay allows full\nclearance of maternal antibody in the infant and avoiding confusing results. Screening should be performed by antibody and, if positive, HCV RNA by PCR.\nSince this child is only 10 months, the next best step would be waiting until she reaches 18 months to let the circulating antibodies cleared. If the antibody titer remains positive beyond this time, HCV RNA serology would be the next step.\nPositive HCV RNA serology indicates presence of hepatitis C virus and infection of the infant. If that is the case, the neonate should be referred to a specialist for further management.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","screen","screening"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"387db531fd6e60a848840ca74a942b571d6a64e1","duplicate_group_id":"exact-387db531fd6e","duplicate_sources":[{"record_id":"133c11e817567dc229c8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1070,"source_qid":"207"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=ex