INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('82ee7a6c9ab908620e87','Amedex 2023.pdf','1074','Mixed/Unclassified','A 27-year-old woman, previously intravenous drug abuser, presents at 8 weeks pregnancy for evaluation. On assessment, she is found to have positive hepatitis C antibody (HCVAb). Which one of the following would be the next best step in
management?','{"A":"Termination of the pregnancy.","B":"Maternal blood PCR for hepatitis C, perinatally.","C":"Screen the infant at 12 months.","D":"Reassure her that the risk of vertical transmission is negligible and nothing needs to be done.","E":"Screen the infant at 18 months."}','B','It is recommended that pregnant women wth a positive hepatitis C virus (HCV) antibody titer, have a PCR test for HCV RNA and liver function tests because the risk of perinatal transmission depends on the presence of HCV RNA. The PCR detects
the presence or absence of the virus and the viral load in the blood, and the genotype.
Liver function tests should be performed at the time of checking HCV RNA status. Since concomitant HIV infection increases the risk of transmission, HIV status should also be checked if not already performed.
With a mother serologically positive for hepatitis C, transmission rate to fetus would be 5%, and higher if the mother becomes infected during pregnancy.
Termination of pregnancy is not advised in this situation; rather the patient should be educated about the risk of transmission of hepatitis C to the infant and screening the infant at 12-18 month of age for hepatitis C. If the infant is found to have
hepatitis C, specialist care would be required.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"209","duplicate_group_id":"exact-d344e343f906","duplicate_sources":[{"record_id":"82ee7a6c9ab908620e87","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1074,"source_qid":"209"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"82ee7a6c9ab908620e87","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1074,"source_qid":"209","domain_hint":"Mixed/Unclassified","stem":"A 27-year-old woman, previously intravenous drug abuser, presents at 8 weeks pregnancy for evaluation. On assessment, she is found to have positive hepatitis C antibody (HCVAb). Which one of the following would be the next best step in\nmanagement?","options":{"A":"Termination of the pregnancy.","B":"Maternal blood PCR for hepatitis C, perinatally.","C":"Screen the infant at 12 months.","D":"Reassure her that the risk of vertical transmission is negligible and nothing needs to be done.","E":"Screen the infant at 18 months."},"source_answer":"B","source_explanation":"It is recommended that pregnant women wth a positive hepatitis C virus (HCV) antibody titer, have a PCR test for HCV RNA and liver function tests because the risk of perinatal transmission depends on the presence of HCV RNA. The PCR detects\nthe presence or absence of the virus and the viral load in the blood, and the genotype.\nLiver function tests should be performed at the time of checking HCV RNA status. Since concomitant HIV infection increases the risk of transmission, HIV status should also be checked if not already performed.\nWith a mother serologically positive for hepatitis C, transmission rate to fetus would be 5%, and higher if the mother becomes infected during pregnancy.\nTermination of pregnancy is not advised in this situation; rather the patient should be educated about the risk of transmission of hepatitis C to the infant and screening the infant at 12-18 month of age for hepatitis C. If the infant is found to have\nhepatitis C, specialist care would be required.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","management","pregnan","screen","screening"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d344e343f906516b93a15578f07a0a27bde021c9","duplicate_group_id":"exact-d344e343f906","duplicate_sources":[{"record_id":"82ee7a6c9ab908620e87","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1074,"source_qid":"209"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
