INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('a82752409ddd9c44c68a','src-v294-687f312c','212','1077','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','Which one of the following will best minimize the risk of mother-to-child transmission of human immune deficiency virus?',NULL,'C','Perinatal HIV transmission rates have been reduced by more than 70 % through:
Treatment of the mother and baby with antiretroviral treatment (ART)
Elective cesarean section
Not breastfeeding
The Pediatric AIDS Clinical Trial Group (PACTG 076) study showed that administration of zidovudine alone, or in combination with other retroviral drugs, to HIV infected women and their newborn, reduces the risk of perinatal transmission by
approximately two thirds (from 25.5 % to 8.3 %). When antiretroviral therapy is combined with elective cesarean section, the risk of vertical transmission falls to 2%.
Rates of transmission are increased in case of:
Advanced maternal illness
High maternal viral load (due to advanced infection or viral activity)
Poor maternal immune status e.g. low CD4 count (also known as T cell count)
Rupture of membranes > 4 hours before birth
Preterm labor
Vaginal delivery
Procedures that may jeopardize the integrity of natural barriers (e.g. fetal scalp electrodes, vigorous suctioning, injections through unwashed skin)
Breastfeeding',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"212","duplicate_group_id":"exact-8cf8fc0e8473","duplicate_sources":[{"record_id":"a82752409ddd9c44c68a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1077,"source_qid":"212"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
