INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b4a33241d24e0a85df38','Amedex 2023.pdf','1085','Mixed/Unclassified','A 25-year-old woman is found to have a urine culture positive for group B streptococcus at 30 weeks gestation. She denies no urinary symptoms such as frequency, dysuria, or urgency, and is otherwise healthy. Which one of the following would be
the next best step in management?','{"A":"Prophylactic penicillin during labour.","B":"Nitrofurantoine.","C":"Cephalexin.","D":"Do vaginal swab in a week and then treat if positive.","E":"Follow up to see if she develops fever."}','C','At the first look and if the question is not read carefully, one may mistake the diagnosis and management of an asymptomatic bacteriuria in a pregnant woman with the notorious group B streptococcus (GBS) colonization.
In cases of coloniation of pregnant women with GBS, the management includes intravenous antibiotics once the labor starts, as an attempt to significantly decrease the chances of early neonatal GBS infection and sepsis with consequent
catastrophic outcomes.
In this case, however, this pregnant woman has asymptomatic bacteriuria. and should be treated with appropriate antibiotics once diagnosed. The recommedned antibiotic regimens include:
First-line: cephalexin 500mg orally, 12 hourly for 10 days (category A)
Second-line: nitrofurantoin 50mg orally, 6 hourly for 10 days (category A)
Third-line: amoxicillin + clavulanate 500+125mg orally, 12-hourly for 10 days (category B1)
There is increased resistance to amoxicillin. This drug should only be used if the susceptibility test is proven.
Women with confirmed bacteriuria should have repeat cultures sent at each antenatal visit or monthly to monitor for recurrent bacteriuria. Ongoing prophylaxis for the duration of the pregnancy should be offered to women with persistent bacteriuria.
Group B streptococcus positive vaginal swabs are not treated in the antenatal period, as group B streptococcus can recolonize at any time after treatment.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"218","duplicate_group_id":"exact-d40a6f4af6fb","duplicate_sources":[{"record_id":"b4a33241d24e0a85df38","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1085,"source_qid":"218"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"b4a33241d24e0a85df38","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1085,"source_qid":"218","domain_hint":"Mixed/Unclassified","stem":"A 25-year-old woman is found to have a urine culture positive for group B streptococcus at 30 weeks gestation. She denies no urinary symptoms such as frequency, dysuria, or urgency, and is otherwise healthy. Which one of the following would be\nthe next best step in management?","options":{"A":"Prophylactic penicillin during labour.","B":"Nitrofurantoine.","C":"Cephalexin.","D":"Do vaginal swab in a week and then treat if positive.","E":"Follow up to see if she develops fever."},"source_answer":"C","source_explanation":"At the first look and if the question is not read carefully, one may mistake the diagnosis and management of an asymptomatic bacteriuria in a pregnant woman with the notorious group B streptococcus (GBS) colonization.\nIn cases of coloniation of pregnant women with GBS, the management includes intravenous antibiotics once the labor starts, as an attempt to significantly decrease the chances of early neonatal GBS infection and sepsis with consequent\ncatastrophic outcomes.\nIn this case, however, this pregnant woman has asymptomatic bacteriuria. and should be treated with appropriate antibiotics once diagnosed. The recommedned antibiotic regimens include:\nFirst-line: cephalexin 500mg orally, 12 hourly for 10 days (category A)\nSecond-line: nitrofurantoin 50mg orally, 6 hourly for 10 days (category A)\nThird-line: amoxicillin + clavulanate 500+125mg orally, 12-hourly for 10 days (category B1)\nThere is increased resistance to amoxicillin. This drug should only be used if the susceptibility test is proven.\nWomen with confirmed bacteriuria should have repeat cultures sent at each antenatal visit or monthly to monitor for recurrent bacteriuria. Ongoing prophylaxis for the duration of the pregnancy should be offered to women with persistent bacteriuria.\nGroup B streptococcus positive vaginal swabs are not treated in the antenatal period, as group B streptococcus can recolonize at any time after treatment.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","drug","duration","management","pregnan","prophyl","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d40a6f4af6fbfb45cb537ab9d5ea3af79950689c","duplicate_group_id":"exact-d40a6f4af6fb","duplicate_sources":[{"record_id":"b4a33241d24e0a85df38","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1085,"source_qid":"218"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_expla