INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2c22217425cd0cbcf466','Amedex 2023.pdf','1089','Mixed/Unclassified','Which one of the following risk factors is not associated with increased risk of group-B streptococcus (GBS) neonatal sepsis?','{"A":"Preterm labor.","B":"GBS bacteriuria in current pregnancy.","C":"Previous baby with GBS-related early onset sepsis.","D":"Rupture of membranes of 10 hours duration.","E":"Maternal temperature greater than or equal to 38°C within 24 hours of giving birth."}','D','Risk factors for early neonatal GBS sepsis include:
Maternal fever more than or equal to 38°C either intrapartum or within 24 hours of giving birth
Group-B streptococcus bacteriuria and colonization in current pregnancy
Rupture of membranes prior to birth for more than 18 hours
Preterm labor (less than 37 weeks)
Previous GBS related early onset sepsis
