INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d811b99873888862505c','Amedex 2023.pdf','1094','Mixed/Unclassified','Which one of the following statements is incorrect regarding endometriosis?','{"A":"Laparoscopy is the best diagnostic test.","B":"It is the commonest cause of chronic pelvic pain in women in most developed countries.","C":"The usual delay in diagnosis is 8 to 10 months with onset in adolescence.","D":"Medical treatment for endometriosis usually does not improve fertility.","E":"Excisional surgery is the treatment of choice for infertility caused by endometriosis."}','C','Option A is correct - Endometriosis is a highly variable condition and diagnosis can be difficult. Confirmation of diagnosis requires laparoscopy in most situations.
Option B is correct - Endometriosis is the most common cause of chronic pelvic pain in most developed countries.
Option C is incorrect - usual delay in diagnosis is about 8 to 10 years and not 8 to 10 months.
Option D is correct - There is strong evidence that medical treatment only relieves symptoms and does not improve fecundity.
Option E is correct - Excisional surgery for endometriosis is usually the treatment of choice as it improves the symptoms, confirms the diagnosis and improves the quality of life in 60-80% of patients.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"332","duplicate_group_id":"exact-b3baae81d653","duplicate_sources":[{"record_id":"d811b99873888862505c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1094,"source_qid":"332"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d811b99873888862505c","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1094,"source_qid":"332","domain_hint":"Mixed/Unclassified","stem":"Which one of the following statements is incorrect regarding endometriosis?","options":{"A":"Laparoscopy is the best diagnostic test.","B":"It is the commonest cause of chronic pelvic pain in women in most developed countries.","C":"The usual delay in diagnosis is 8 to 10 months with onset in adolescence.","D":"Medical treatment for endometriosis usually does not improve fertility.","E":"Excisional surgery is the treatment of choice for infertility caused by endometriosis."},"source_answer":"C","source_explanation":"Option A is correct - Endometriosis is a highly variable condition and diagnosis can be difficult. Confirmation of diagnosis requires laparoscopy in most situations.\nOption B is correct - Endometriosis is the most common cause of chronic pelvic pain in most developed countries.\nOption C is incorrect - usual delay in diagnosis is about 8 to 10 years and not 8 to 10 months.\nOption D is correct - There is strong evidence that medical treatment only relieves symptoms and does not improve fecundity.\nOption E is correct - Excisional surgery for endometriosis is usually the treatment of choice as it improves the symptoms, confirms the diagnosis and improves the quality of life in 60-80% of patients.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b3baae81d65334bbbe698f8978af18d6a27ef9df","duplicate_group_id":"exact-b3baae81d653","duplicate_sources":[{"record_id":"d811b99873888862505c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1094,"source_qid":"332"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
