INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('1ccee3fb24d2dfef8e46','src-v294-687f312c','352','1105','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','An 18-year-old girl was vaccinated against rubella as a part of antenatal work up and was advised to avoid pregnancy for at least 3 months. She was found to be pregnant 4 weeks after the rubella vaccination and is concerned about the outcome.
Which one of the following would be the correct management?',NULL,'B','It is recommended that women who receive rubella vaccine avoid pregnancy for 3 months post-vaccination, despite the fact that no study has proven the increased risk of congenital rubella syndrome if the patient becomes pregnant during this
period.
If a patient becomes pregnant within 3 months of receiving the vaccine, reassurance is all needed and pregnancy should be continued.
Termination of pregnancy is considered if there is serological evidence of rubella infection during first trimester of pregnancy.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"352","duplicate_group_id":"exact-fe7b830d7606","duplicate_sources":[{"record_id":"1ccee3fb24d2dfef8e46","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1105,"source_qid":"352"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
