INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('277be51e8a648c9e6de8','Amedex 2023.pdf','1107','Mixed/Unclassified','A 32-year-old woman comes to your office to discuss about her recent cervical screening test result with you. The result reports low-grade squamous intraepithelial lesion (LSIL). Her last testing wilth the old pap smear 2 years ago was reported
normal. Which one of the following would be the most appropriate action to take?','{"A":"Repeat the test in one year.","B":"Refer for colposcopy.","C":"Refer to an oncologist.","D":"Repeat the test smear in 6 months.","E":"Repeat the test in 2 years."}','A','The following table includes guidelines for management of different pap smear results:
 
Pap smear report
Investigation and management
Negative test – inflammatory cells
Repeat the test in 5 years
Unsatisfactory test
Repeat the smear in 6-12 weeks – this time period allows regeneration of the cells
Low-grade squamous intraepithelial lesion (LSIL)
Possible LSIL
And
Definite LSIL
Repeat the test in 12 months High-grade squamous intraepithelial lesion (HSIL)
Possible HSIL
Definite HSIL
Referral to specialist for colposcopy
Glandular abnormalities including adenocarcinoma in situ
Referral to gynecologist
Invasive squamous cell carcinoma or adenocarcinoma
Referral to appropriate specialist gynecologist or unit
Inconclusive – raising possibility of high-grade disease
Referral for colposcopy and possible biopsy
According to this guideline, as this woman had a normal pap smear 2 years ago, the next step would be repeating the smear in 12 months (one year).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"417","duplicate_group_id":"exact-e48bfdc02aed","duplicate_sources":[{"record_id":"277be51e8a648c9e6de8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1107,"source_qid":"417"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"277be51e8a648c9e6de8","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1107,"source_qid":"417","domain_hint":"Mixed/Unclassified","stem":"A 32-year-old woman comes to your office to discuss about her recent cervical screening test result with you. The result reports low-grade squamous intraepithelial lesion (LSIL). Her last testing wilth the old pap smear 2 years ago was reported\nnormal. Which one of the following would be the most appropriate action to take?","options":{"A":"Repeat the test in one year.","B":"Refer for colposcopy.","C":"Refer to an oncologist.","D":"Repeat the test smear in 6 months.","E":"Repeat the test in 2 years."},"source_answer":"A","source_explanation":"The following table includes guidelines for management of different pap smear results:\n \nPap smear report\nInvestigation and management\nNegative test – inflammatory cells\nRepeat the test in 5 years\nUnsatisfactory test\nRepeat the smear in 6-12 weeks – this time period allows regeneration of the cells\nLow-grade squamous intraepithelial lesion (LSIL)\nPossible LSIL\nAnd\nDefinite LSIL\nRepeat the test in 12 months High-grade squamous intraepi