INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('431645f2617fef8fd0ee','Amedex 2023.pdf','1115','Mixed/Unclassified','48-year-old woman with past history of hysterectomy comes to discuss about hormone replacement therapy (HRT) for her post-menopausal symptoms, while she is also concerned about the associated risk of breast cancer. Which one of the
following is the best advice for her?','{"A":"Postmenopausal women with BMI <25 have a lower relative risk of developing breast cancer associated with estrogen-only HRT than those women with higher BMIs.","B":"There is consistent evidence indicating that tibolone may be associated with an increased risk of breast cancer.","C":"Use of estrogen-alone HRT for up to seven years appears to have no effect on risk of breast cancer.","D":"She does not need hormone replacement therapy.","E":"She should use hormone replacement therapy only for few weeks."}','C','The best option for HRT in women who do not have a uterus due to previous hysterectomy is estrogen alone. These patients should be advised that this regimen seems not to increase the risk of developing breast cancer if used for only up to
seven years. Beyond this time, however, the risk increases proportionate to the duration of HRT.
Post-menopausal women with a BMI less than 25 have a higher relative risk of contracting breast cancer associated with estrogen-only hormone replacement therapy, than women with higher BMI. The reason can be attributed to less metabolization
of estrogen in the adipose tissue.
Tibolone is used for hormone replacement therapy and for treatment of endometriosis. There is very inconsistent evidence indicating that tibolone may be associated with an increased risk of breast cancer.
While this woman has menopausal symptoms, advising against HRT is not appropriate. She can use HRT for a longer duration compared to women who still have uterus and are at risk of developing endometrial cancer.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-d6e9c7fd134f","duplicate_sources":[{"record_id":"431645f2617fef8fd0ee","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1115,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"431645f2617fef8fd0ee","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1115,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"48-year-old woman with past history of hysterectomy comes to discuss about hormone replacement therapy (HRT) for her post-menopausal symptoms, while she is also concerned about the associated risk of breast cancer. Which one of the\nfollowing is the best advice for her?","options":{"A":"Postmenopausal women with BMI <25 have a lower relative risk of developing breast cancer associated with estrogen-only HRT than those women with higher BMIs.","B":"There is consistent evidence indicating that tibolone may be associated with an increased risk of breast cancer.","C":"Use of estrogen-alone HRT for up to seven years appears to have no effect on risk of breast cancer.","D":"She does not need hormone replacement therapy.","E":"She should use hormone replacement therapy only for few weeks."},"source_answer":"C","source_explanation":"The best option for HRT in women who do not have a uterus due to previous hysterectomy is estrogen alone. These patients should be advised that this regimen seems not to increase the risk of developing breast cancer if used for only up to\nseven years. Beyond this time, however, the risk increases proportionate to the duration of HRT.\nPost-menopausal women with a BMI less than 25 have a higher relative risk of contracting breast cancer associated with estrogen-only hormone replacement therapy, than women with higher BMI. The reason can be attributed to less metabolization\nof estrogen in the adipose tissue.\nTibolone is used for hormone replacement therapy and for treatment of endometriosis. There is very inconsistent evidence indicating that tibolone may be associated with an increased risk of breast cancer.\nWhile this woman has menopausal symptoms, advising against HRT is not appropriate. She can use HRT for a longer duration compared to women who still have uterus and are at risk of developing endometrial cancer.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["duration","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d6e9c7fd134f34c433fbc631b847e222df89473d","duplicate_group_id":"exact-d6e9c7fd134f","duplicate_sources":[{"record_id":"431645f2617fef8fd0ee","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1115,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_